import type { Meta } from "@storybook/react";
import { fn } from "@storybook/test";
import React from "react";

import { huge_data_set } from "../../../../data/huge_data_set";
import { sales_records_dataset } from "../../../../data/sales_records_dataset";
import { argTypes } from "../../../../storybook/argTypes";
import { jitterFields, withDataControls } from "../../../../storybook/dataControls";
import { createCanvasTest, createSVGTest } from "../../../testUtils";
import { XAxis, YAxis, ZAxis } from "../../Axis";
import { XYChart } from "../../XYChart";
import { Scatter } from "./Scatter";
import { Scatters } from "./Scatters";

const { width, height, margin, useCanvas, theme, color } = argTypes;

export default {
  title: "Charts/XYCharts/Scatter",
  component: Scatter,
  parameters: {
    docs: {
      transformSource: (src) => {
        src = src.replace(/data={\[.*?\]}/gs, "data={[ ...dataset ]}");
        src = src.replaceAll(/undefined,?/g, "");
        src = src.replace(/^\s*\n/gm, "");
        return src;
      },
    },
    chromatic: { delay: 300 },
  },
  args: {
    onClick: fn(),
    onMouseOver: fn(),
    onMouseOut: fn(),
  },
  argTypes: {
    useCanvas,
    width,
    height,
    theme,
    color,
    leftMargin: margin,
    rightMargin: margin,
    topMargin: margin,
    bottomMargin: margin,
    radius: {
      description: "The radius of the points on the chart",
      control: { type: "range", min: 1, max: 100 },
      defaultValue: { summary: 5 },
    },
  },
} as Meta<typeof Scatter>;

const ScatterTemplate = (args) => (
  <XYChart
    data={args.data}
    plotMargin={{
      left: args.leftMargin,
      right: args.rightMargin,
      top: args.topMargin,
      bottom: args.bottomMargin,
    }}
    width={args.width}
    height={args.height}
    animationDuration={args.animationDuration}
    theme={args.theme}
    useCanvas={args.useCanvas}
    onClick={args.onClick}
    onMouseOver={args.onMouseOver}
    onMouseOut={args.onMouseOut}
  >
    <YAxis fields={[args.y, args.y2, args.y3]} />
    <XAxis fields={[args.x]} />
    <Scatter
      x={args.x}
      y={args.y}
      radius={args.radius}
      color={args.color}
      noClip
    />
  </XYChart>
);

// Numeric fields to animate; the rest (Country, Item Type, dates, ...) stay untouched.
const salesFields = ["Units Sold", "Unit Price", "Unit Cost", "Total Revenue", "Total Cost", "Total Profit"];

const scatterDataControls = {
  initialData: sales_records_dataset,
  randomize: (row: (typeof sales_records_dataset)[number]) => jitterFields(row, salesFields, 0.3),
  // Clones a random existing row and jitters it, since the source dataset is small enough that
  // Basic already includes every row
  createPoint: (current: typeof sales_records_dataset) =>
    jitterFields(current[Math.floor(Math.random() * current.length)], salesFields, 0.3),
  minLength: 5,
};

const ScatterTemplateWithControls = withDataControls(ScatterTemplate, scatterDataControls);

const ScattersTemplate = (args) => (
  <XYChart
    plotMargin={{
      left: args.leftMargin,
      right: args.rightMargin,
      top: args.topMargin,
      bottom: args.bottomMargin,
    }}
    data={sales_records_dataset}
    width={args.width}
    height={args.height}
    animationDuration={args.animationDuration}
    theme={args.theme}
    useCanvas={args.useCanvas}
    onClick={args.onClick}
    onMouseOver={args.onMouseOver}
    onMouseOut={args.onMouseOut}
  >
    <YAxis fields={[args.y, args.y2, args.y3]} />
    <XAxis fields={[args.x]} />
    <Scatters x={args.x} ys={[args.y, args.y2, args.y3]} radius={args.radius} />
  </XYChart>
);

export const Basic = {
  name: "Basic Plot",
  render: ScatterTemplateWithControls,
  args: {
    useCanvas: false,
    width: 800,
    height: 500,
    animationDuration: 250,
    color: "#99C1DC",
    theme: "light",
    radius: 5,
    leftMargin: 70,
    rightMargin: 40,
    topMargin: 40,
    bottomMargin: 40,
    data: sales_records_dataset,
    y: "Total Profit",
    x: "Units Sold",
  },
  play: createSVGTest("circle", { clientX: 773, clientY: 227 }),
};

export const Radius = {
  name: "Custom Radius",
  render: ScatterTemplate,
  args: {
    ...Basic.args,
    radius: 15,
  },
};

export const Color = {
  name: "Custom Color",
  render: ScatterTemplate,
  args: {
    ...Basic.args,
    color: "orange",
  },
};

export const Canvas = {
  name: "Using Canvas",
  render: ScatterTemplateWithControls,
  args: {
    ...Basic.args,
    useCanvas: true,
  },
  play: createCanvasTest({ clientX: 773, clientY: 227 }),
};

export const MultipleScatter = {
  name: "Mutiple Scatter Plots",
  render: ScattersTemplate,
  args: {
    ...Basic.args,
    y2: "Total Revenue",
    y3: "Total Cost",
  },
};

export const MultipleScatterCanvas = {
  name: "Mutiple Scatter Plots using Canvas",
  render: ScattersTemplate,
  args: {
    ...Basic.args,
    y2: "Total Revenue",
    y3: "Total Cost",
    useCanvas: true,
  },
};

const BubbleSizeTemplate = (args) => (
  <XYChart
    data={args.data}
    plotMargin={{
      left: args.leftMargin,
      right: args.rightMargin,
      top: args.topMargin,
      bottom: args.bottomMargin,
    }}
    width={args.width}
    height={args.height}
    animationDuration={args.animationDuration}
    theme={args.theme}
    useCanvas={args.useCanvas}
  >
    <YAxis fields={[args.y]} />
    <XAxis fields={[args.x]} />
    <ZAxis fields={[args.z]} tickFormat={(value) => `$${value}`} />
    <Scatter x={args.x} y={args.y} z={args.z} color={args.color} noClip />
  </XYChart>
);

export const BubbleSize = {
  name: "Sizing bubbles with ZAxis",
  render: BubbleSizeTemplate,
  args: {
    ...Basic.args,
    z: "Unit Price",
  },
};

export const ProgresssiveRendering = {
  name: "Progressive Rendering large datasets",
  render: ScatterTemplate,
  args: {
    ...Basic.args,
    animationDuration: 0,
    data: huge_data_set,
    height: 500,
    useCanvas: true,
    radius: 3,
    width: 800,
  },
  parameters: {
    chromatic: { disableSnapshot: true },
  },
};
